 await f.state({visualAlternatives:aview({revision:1,busy:true,records:[running],active})});await f.send({type:'visualAlternativesPreview',projectId:project.id,...active});
 const frame=f.page.locator('[data-foundation-alternative-canvas]');await expect(frame).toBeVisible();await expect.poll(async()=>(await f.outbound()).filter(v=>v.type==='visualAlternativesPreviewReady').length).toBe(1);
 const ack=(await f.outbound()).find(v=>v.type==='visualAlternativesPreviewReady');assert.deepEqual(ack,{type:'visualAlternativesPreviewReady',projectId:project.id,comparisonId:record.id,variantId:'baseline',nonce:active.nonce,phase:'connect',session:runtime.session,viewId:runtime.viewId,documentId:'3'.repeat(32),pageVersion:1,route:'/alternative-frame',requested});
 await frame.evaluate(node=>node.dataset.testIdentity='preserved');await f.state({visualAlternatives:aview({revision:2,busy:true,records:[running],active})});await expect(frame).toHaveAttribute('data-test-identity','preserved');await expect(f.page.locator('[data-foundation-runtime-canvas]')).toHaveCount(1);await expect(f.page.locator('.runtime-studio .design-canvas .design-viewport > iframe[data-foundation-runtime-canvas]')).toHaveCount(1);const geometry=await frame.evaluate(node=>{const r=node.getBoundingClientRect(),v=node.parentElement.getBoundingClientRect();return {x:r.x,y:r.y,width:r.width,height:r.height,right:r.right,bottom:r.bottom,viewportWidth:innerWidth,viewportHeight:innerHeight,parentWidth:v.width,parentHeight:v.height,cssWidth:node.clientWidth,cssHeight:node.clientHeight};});assert.equal(geometry.cssWidth,960);assert.equal(geometry.cssHeight,680);assert.ok(Math.abs(geometry.width-geometry.parentWidth)<0.1);assert.ok(Math.abs(geometry.height-geometry.parentHeight)<0.1);assert.ok(geometry.x>=0&&geometry.y>=0&&geometry.right<=geometry.viewportWidth&&geometry.bottom<=geometry.viewportHeight);
 const capturePreview={...active,phase:'capture',nonce:'8'.repeat(32),runtime:{...active.runtime,documentId:'3'.repeat(32),pageVersion:1,pagePath:'/alternative-frame',status:'connected'}};await f.state({visualAlternatives:aview({revision:3,busy:true,records:[running],active:capturePreview})});await f.send({type:'visualAlternativesPreview',projectId:project.id,...capturePreview});await expect.poll(async()=>(await f.outbound()).filter(v=>v.type==='visualAlternativesPreviewReady').length).toBe(2);assert.equal((await f.outbound()).filter(v=>v.type==='visualAlternativesPreviewReady').at(-1).phase,'capture');await expect(frame).toHaveAttribute('data-test-identity','preserved');
 assert.equal((await f.outbound()).some(v=>v.type==='designObserved'||v.type==='runtime'),false);await f.page.getByRole('button',{name:'Refine',exact:true}).click();await expect(frame).toBeHidden();await expect(f.page.locator('.runtime-studio .design-canvas .design-viewport > iframe[data-foundation-runtime-canvas]')).toHaveCount(0);await expect(f.page.getByRole('button',{name:'Stop comparison',exact:true})).toBeVisible();await f.page.getByRole('button',{name:'Understand',exact:true}).click();await expect(frame).toBeHidden();await expect(f.page.getByRole('button',{name:'Stop comparison',exact:true})).toBeVisible();await f.page.getByRole('button',{name:'View comparison',exact:true}).click();await expect(frame).toHaveAttribute('data-test-identity','preserved');
 await f.page.getByRole('button',{name:'Stop comparison',exact:true}).click();await expect(f.page.getByRole('button',{name:'Stopping…',exact:true})).toBeDisabled();assert.deepEqual((await f.outbound()).filter(v=>v.type==='visualAlternatives').at(-1),{type:'visualAlternatives',action:'stop',projectId:project.id,id:record.id});await f.state({visualAlternatives:aview({revision:3,records:[{...running,status:'cancelled'}]})});await expect(frame).toHaveCount(0);await f.open();await expect(f.history()).toContainText('Stopped');
