const wholeGroup={schemaVersion:1,id:'whole-group',projectId:project.id,revision:2,title:'Save with clarity',summary:'Coordinate the label and corner radius.',status:'proposed',origin:'ai',requestId:'group-build',files:[file,groupFile].map((value,index)=>({id:'group-file-'+index,path:value.path,before:value.source,after:value.source+'\n',baseRevision:value.revision})),context:[file,groupFile].map(({path,revision})=>({path,revision})),verification:[],verificationStatus:'not-run'};
const groupSession=(group=wholeGroup,extra={})=>({current:group,versions:[],busy:false,storage:{status:'saved'},assessment:{files:group.files.map(value=>({path:value.path,revision:value.baseRevision,state:group.status==='applied'?'after':'before',dirty:false})),canApply:group.status==='proposed',canUndo:group.status==='applied',canRecover:false,canPrepareAcceptance:true},checkpoints:[],...extra});
const groupHistory={schemaVersion:3,projectId:project.id,revision:1,activeId:'group-conversation',conversations:[{id:'group-conversation',title:'Save clearly',archived:false,createdAt:stamp(0),updatedAt:stamp(1),turns:[{id:'group-turn',requestId:wholeGroup.requestId,intent:'build',question:'Coordinate this save interaction.',context:wholeGroup.context,state:'complete',started:true,answer:'',changeSet:wholeGroup}]}],storage:{status:'saved'}};
const groupProjection={id:wholeGroup.id,proposalBasis:'6'.repeat(64),title:wholeGroup.title,paths:wholeGroup.files.map(value=>value.path),canPrepare:true,reason:'',scenarios:[achoice]};
const groupView=(extra={})=>aview({proposal:null,groupProposal:groupProjection,...extra});
const groupState=(extra={})=>({project:{...project,files:[file,groupFile].map(({path})=>({path}))},proposal:null,openFiles:[file,groupFile],changeSetSession:groupSession(),conversations:groupHistory,visualAlternatives:groupView(),...extra});
const groupRecord=(id,name)=>{
 const {path,proposalId,beforeHash,afterHash,...shared}=retained(id,name,id==='group-a'?'5':'6');
 return {...shared,source:{kind:'change-set',groupId:wholeGroup.id,groupRevision:wholeGroup.revision,groupDigest:'7'.repeat(64),files:wholeGroup.files.map(value=>({path:value.path,beforeHash:createHash('sha256').update(value.before).digest('hex'),afterHash:createHash('sha256').update(value.after).digest('hex')}))},candidate:{name,metadataDigest:'5'.repeat(64)}};
};
const groupA=groupRecord('group-a','Quiet saving'),groupB=groupRecord('group-b','Clear saving');
const groupResults=(extra={})=>groupView({records:[groupA,groupB],comparisonPairs:[compatible(groupA.id,groupB.id)],reviewChoices:[{id:groupA.id,canReview:true,reason:''},{id:groupB.id,canReview:true,reason:''}],...extra});
const localGroup={...wholeGroup,id:'local-retained-group',origin:'alternative',requestId:undefined,revision:0,title:groupA.candidate.name};

test('whole group preparation reuses explicit scenario controls and never sends source bytes',async t=>{
 const f=await fixture(t);await f.state(groupState());await expect(f.panel()).toHaveAttribute('data-alternative-source-kind','change-set');await expect(f.panel()).toHaveAttribute('data-alternative-source-id',wholeGroup.id);await expect(f.panel()).toContainText('Entire group · 2 files');await f.panel().locator('summary').filter({hasText:'Included files'}).click();for(const value of wholeGroup.files)await expect(f.panel()).toContainText(value.path);await f.choose();await f.panel().getByRole('textbox',{name:'Alternative name'}).fill('Quiet saving');await f.panel().getByRole('button',{name:'Prepare comparison'}).click();
 const messages=(await f.outbound()).filter(value=>value.type==='visualAlternatives');assert.deepEqual(messages,[{type:'visualAlternatives',action:'prepare',projectId:project.id,expectedRevision:0,sourceKind:'change-set',proposalId:wholeGroup.id,proposalBasis:groupProjection.proposalBasis,candidateName:'Quiet saving',scenarioId:scenario.id,recipeId:recipe.id,requested,captureEach:false}]);assert.equal(JSON.stringify(messages).includes(groupFile.source),false);
 const prepared={...groupA,captureEach:false,status:'preparing'};await f.state({visualAlternatives:groupView({revision:1,busy:true,records:[prepared]})});await expect(f.page.getByRole('button',{name:'Stop comparison',exact:true})).toBeEnabled();await f.state({visualAlternatives:groupView({revision:2,records:[{...prepared,status:'ready'}]})});await expect(f.history().getByRole('button',{name:'Run comparison',exact:true})).toBeVisible();assert.equal((await f.outbound()).some(value=>value.action==='run'||value.type==='changeSetAction'),false);
});
test('group drafts restore by exact source kind and basis, with explicit unsupported or stale reasons',async t=>{
 const f=await fixture(t);await f.state(groupState());await f.choose();const name=f.panel().getByRole('textbox',{name:'Alternative name'});await name.fill('Prepared group');await name.focus();await f.state({visualAlternatives:groupView({revision:1})});await expect(name).toBeFocused();for(const reason of ['Use whole proposal before preparing this comparison.','Resolve an unsaved changed file before comparing.','All changed files must belong to this feature.','The saved group source changed.','Connect the instrumented app to discover its scenario recipes.']){await f.state({visualAlternatives:groupView({groupProposal:{...groupProjection,canPrepare:false,reason}})});await expect(f.panel()).toContainText(reason);await expect(f.panel().getByRole('button',{name:'Prepare comparison'})).toBeDisabled();}
 await f.page.reload();await f.state(groupState());await expect(name).toHaveValue('Prepared group');await expect(f.panel().getByRole('combobox',{name:'Comparison recipe'})).toHaveValue(recipe.id);assert.equal((await f.outbound()).some(value=>value.type==='visualAlternatives'),false);await f.state({visualAlternatives:groupView({groupProposal:{...groupProjection,proposalBasis:'9'.repeat(64)}})});await expect(name).toHaveValue(wholeGroup.title);await expect(f.panel().getByRole('combobox',{name:'Comparison recipe'})).toHaveValue('');
 await f.state({proposal:{...proposal,id:wholeGroup.id},changeSetSession:null,visualAlternatives:aview({proposal:{...aview().proposal,id:wholeGroup.id,proposalBasis:groupProjection.proposalBasis}})});await expect(f.panel()).toHaveAttribute('data-alternative-source-kind','token');await expect(name).toHaveValue(proposal.title);await expect(f.panel().getByRole('combobox',{name:'Comparison recipe'})).toHaveValue('');
});
test('retained group comparison uses source snapshots and exact file facts without a fake token or path',async t=>{
 const f=await fixture(t);await f.state(groupState({changeSetSession:null,visualAlternatives:groupResults()}));await chooseRetained(f,groupA.id,groupB.id);await compareRetained(f);const side=selectedComparison(f).getByRole('region',{name:'Quiet saving evidence',exact:true});await expect(side).toContainText('2 changed files');await expect(side).toContainText('Source snapshot');await expect(side).not.toContainText('Source revision');await expect(side).not.toContainText('undefined');await side.locator('summary').filter({hasText:'Changed files'}).click();for(const value of groupA.source.files){await expect(side).toContainText(value.path);await expect(side).toContainText(value.beforeHash.slice(0,12)+' → '+value.afterHash.slice(0,12));}await expect(side.getByRole('button',{name:'Review this group',exact:true})).toBeEnabled();await expect(side.getByRole('button',{name:'Review this change',exact:true})).toHaveCount(0);await selectedComparison(f).getByRole('button',{name:'Show captures'}).click();assert.deepEqual((await f.outbound()).filter(value=>value.action==='image').map(value=>[value.id,value.captureId]),[[groupA.id,groupA.id+'-alternative'],[groupB.id,groupB.id+'-alternative']]);
 await f.page.reload();await f.state(groupState({changeSetSession:null,visualAlternatives:groupResults()}));await expect(selectedComparison(f)).toHaveAttribute('data-comparison-left',groupA.id);await expect(selectedComparison(f).getByRole('img')).toHaveCount(0);assert.equal((await f.outbound()).some(value=>value.type==='visualAlternatives'),false);
});
test('group review is blocked by any active source change and acknowledges only the exact retained candidate',async t=>{
 const f=await fixture(t);await f.state(groupState({visualAlternatives:groupResults()}));await chooseRetained(f,groupA.id,groupB.id);await compareRetained(f);const side=selectedComparison(f).getByRole('region',{name:'Quiet saving evidence',exact:true});for(const reason of ['Discard the current group before reviewing this alternative.','Discard the current token proposal before reviewing this alternative.','The saved comparison source is stale.']){await f.state({visualAlternatives:groupResults({reviewChoices:[{id:groupA.id,canReview:false,reason}]})});await expect(side).toContainText(reason);const button=side.getByRole('button',{name:'Review this group'});await expect(button).toBeDisabled();await button.dispatchEvent('click');}assert.equal((await f.outbound()).some(value=>value.action==='review'),false);
 await f.state({changeSetSession:null,visualAlternatives:groupResults()});await side.getByRole('button',{name:'Review this group'}).click();assert.deepEqual((await f.outbound()).filter(value=>value.action==='review').at(-1),{type:'visualAlternatives',action:'review',projectId:project.id,expectedRevision:0,id:groupA.id,metadataDigest:groupA.candidate.metadataDigest});await f.send({type:'visualAlternativesReview',projectId:project.id,id:groupB.id,metadataDigest:groupA.candidate.metadataDigest,changeSetId:'wrong'});await expect(f.page.getByRole('button',{name:'Cancel review'})).toBeVisible();await f.send({type:'visualAlternativesReview',projectId:project.id,id:groupA.id,metadataDigest:groupA.candidate.metadataDigest,changeSetId:localGroup.id,changeSetBasis:'8'.repeat(64)});await expect(side).toContainText('Opened for source review. Apply remains separate.');assert.equal((await f.outbound()).some(value=>value.type==='changeSetAction'||value.type==='proposalApply'),false);
});
test('local retained authority enables only explicit whole Apply and Undo without AI provenance or extra workflows',async t=>{
 const f=await fixture(t),card=f.page.locator(`[data-artifact-id="change-set/${localGroup.id}"]`);await f.state(groupState({conversations:null,changeSetSession:groupSession(localGroup,{alternativeAuthority:{groupId:localGroup.id,canApply:true,canUndo:false}}),visualAlternatives:groupResults()}));await expect(card).toContainText('Retained alternative');await expect(card).not.toContainText('AI interpretation');await expect(card.getByRole('button',{name:'Apply all',exact:true})).toBeEnabled();for(const name of ['Choose changes','Refine group','Restore version','Prepare workspace','Run check','Create check plan'])await expect(card.getByRole('button',{name,exact:true})).toHaveCount(0);await card.getByRole('combobox',{name:'Changed file'}).selectOption(localGroup.files[1].id);await card.getByRole('button',{name:'Open native diff'}).click();await card.getByRole('button',{name:'Apply all'}).click();assert.deepEqual((await f.outbound()).filter(value=>value.type==='changeSetAction'),[{type:'changeSetAction',action:'diff',projectId:project.id,changeSetId:localGroup.id,expectedRevision:0,fileId:localGroup.files[1].id},{type:'changeSetAction',action:'apply',projectId:project.id,changeSetId:localGroup.id,expectedRevision:0}]);
 const applied={...localGroup,status:'applied',revision:1};await f.state({changeSetSession:groupSession(applied,{alternativeAuthority:{groupId:localGroup.id,canApply:false,canUndo:true}})});await expect(card.getByRole('button',{name:'Undo all',exact:true})).toBeEnabled();await card.getByRole('button',{name:'Undo all'}).click();assert.deepEqual((await f.outbound()).filter(value=>value.type==='changeSetAction').at(-1),{type:'changeSetAction',action:'undo',projectId:project.id,changeSetId:localGroup.id,expectedRevision:1});
 await f.state({changeSetSession:groupSession(localGroup,{alternativeAuthority:{groupId:'other',canApply:true,canUndo:true}})});await expect(card.getByRole('button',{name:'Apply all'})).toBeDisabled();await expect(card).toContainText('Retained source authority is unavailable');await f.state({changeSetSession:groupSession(localGroup,{alternativeAuthority:{groupId:localGroup.id,canApply:false,canUndo:false,reason:'The saved source changed.'}})});await expect(card.getByRole('button',{name:'Apply all'})).toBeDisabled();await expect(card).toContainText('The saved source changed.');
 await f.state({changeSetSession:groupSession(wholeGroup,{alternativeAuthority:{groupId:wholeGroup.id,canApply:true,canUndo:true}})});await expect(f.page.getByRole('button',{name:'Apply all'})).toBeDisabled();
});
test('alternative prepare and review lock standard group actions and preserve cancellable review',async t=>{
 const f=await fixture(t);await f.state(groupState());await f.choose();await f.panel().getByRole('button',{name:'Prepare comparison'}).click();for(const name of ['Apply all','Discard group','Choose changes','Check source'])await expect(f.page.getByRole('button',{name,exact:true})).toBeDisabled();await f.page.getByRole('button',{name:'Apply all'}).dispatchEvent('click');assert.equal((await f.outbound()).some(value=>value.type==='changeSetAction'),false);await f.state({visualAlternatives:groupResults({error:'Preparation stopped.'})});await expect(f.page.getByRole('button',{name:'Discard group'})).toBeEnabled();
 await f.state({changeSetSession:groupSession(localGroup,{alternativeAuthority:{groupId:localGroup.id,canApply:true,canUndo:false}}),visualAlternatives:groupResults({busy:true,operation:{action:'review',id:groupA.id}})});await expect(f.page.getByRole('button',{name:'Apply all'})).toBeDisabled();await expect(f.page.getByRole('button',{name:'Cancel review'})).toBeEnabled();await f.page.getByRole('button',{name:'Cancel review'}).click();assert.deepEqual((await f.outbound()).filter(value=>value.type==='visualAlternatives').at(-1),{type:'visualAlternatives',action:'stop',projectId:project.id,id:groupA.id});
});
for(const theme of ['light','dark'])test(theme+' group alternatives remain bounded and keyboard accessible at320px',async t=>{
 const f=await fixture(t,{theme,width:320});await f.state(groupState({visualAlternatives:groupResults()}));await f.choose();const name=f.panel().getByRole('textbox',{name:'Alternative name'});await name.fill('Careful saving');await name.focus();await f.state({visualAlternatives:groupResults({revision:1})});await expect(name).toBeFocused();await chooseRetained(f,groupA.id,groupB.id);await compareRetained(f);await selectedComparison(f).getByRole('region',{name:'Quiet saving evidence',exact:true}).locator('summary').filter({hasText:'Changed files'}).click();const size=await f.page.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth,main:document.querySelector('main').clientWidth,content:document.querySelector('main').scrollWidth}));assert.ok(size.scroll<=size.width&&size.content<=size.main,JSON.stringify(size));await selectedComparison(f).scrollIntoViewIfNeeded();await f.page.screenshot({path:join(root,'desktop/tests/artifacts/scoped-group-alternatives-'+theme+'-320.png'),fullPage:true});
});
